import React, { useState, useEffect } from "react";
import { db } from "../../../firebaseConfig";
import { collection, query, where, getDocs, addDoc } from "firebase/firestore";
import { useParams, useNavigate } from "react-router-dom";
import "./Exam.css"; // Assume a separate file for styles

const Exam = () => {
  const { subject } = useParams(); // Get the subject from URL params
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [studentName, setStudentName] = useState("");
  const [studentClass, setStudentClass] = useState("");
  const [score, setScore] = useState(null);
  const navigate = useNavigate(); // To navigate after exam submission

  useEffect(() => {
    const fetchQuestions = async () => {
      setLoading(true);
      try {
        const q = query(
          collection(db, "exams"),
          where("subject", "==", subject)
        );
        const querySnapshot = await getDocs(q);

        const examQuestions = [];
        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (data.questions) {
            examQuestions.push(...data.questions); // Add questions from the Firestore document
          }
        });

        setQuestions(examQuestions);
        setAnswers(new Array(examQuestions.length).fill("")); // Initialize answers array
      } catch (error) {
        console.error("Error fetching questions:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchQuestions(); // Fetch questions when the page loads
  }, [subject]);

  const handleAnswerChange = (index, value) => {
    const updatedAnswers = [...answers];
    updatedAnswers[index] = value;
    setAnswers(updatedAnswers);
  };

  const handleSubmit = async () => {
    if (!studentName || !studentClass) {
      alert("Please enter your name and class.");
      return;
    }

    // Assuming correct answers are fetched from the Firestore document
    const correctAnswers = questions.map((q) => q.correctAnswer); // Correct answers from Firestore

    // Calculate score by comparing normalized answers
    const calculatedScore = answers.reduce((score, answer, index) => {
      const studentAnswer = answer.trim().toLowerCase(); // Normalize student input
      const correctAnswer = correctAnswers[index]?.trim().toLowerCase(); // Normalize correct answer

      console.log(`Student's Answer: "${studentAnswer}", Correct Answer: "${correctAnswer}"`); // Debugging line

      return studentAnswer === correctAnswer ? score + 1 : score;
    }, 0);

    setScore(calculatedScore); // Set the score

    try {
      // Submit exam data to Firestore
      await addDoc(collection(db, "examResults"), {
        studentName,
        studentClass,
        subject,
        answers,
        score: calculatedScore,
        timestamp: new Date(),
      });

      alert("Exam submitted successfully!");

      // Redirect to the score view page and pass the score data
      navigate("/view-score", { state: { score: calculatedScore, studentName, studentClass, subject } });

    } catch (error) {
      console.error("Error submitting exam:", error);
    }
  };

  return (
    <div className="exam-container">
      <h2>Exam: {subject}</h2>
      <div className="student-info">
        <input
          type="text"
          placeholder="Enter your name"
          value={studentName}
          onChange={(e) => setStudentName(e.target.value)}
          className="student-name-input"
        />
        <input
          type="text"
          placeholder="Enter your class"
          value={studentClass}
          onChange={(e) => setStudentClass(e.target.value)}
          className="student-class-input"
        />
      </div>
      {loading ? (
        <p>Loading questions...</p>
      ) : (
        <form onSubmit={(e) => e.preventDefault()} className="exam-form">
          {questions.map((q, index) => (
            <div key={index} className="question-container">
              <div className="question">
                <p>{index + 1}. {q.question}</p>
              </div>
              <input
                type="text"
                value={answers[index]}
                onChange={(e) => handleAnswerChange(index, e.target.value)}
                placeholder="Your answer"
                className="answer-input"
              />
            </div>
          ))}
          <button
            onClick={handleSubmit}
            className="submit-exam-btn"
          >
            Submit Exam
          </button>
        </form>
      )}
    </div>
  );
};

export default Exam;
